const seeds: Seed[] = [
  { id:"formal-or-familiar",title:"A question of register",subtitle:"Ajuste formalidade sem perder naturalidade.",objective:"Escolher entre alternativas formais e familiares, preservando intenção e relação com o público.",focus:"Registro e intenção",intro:"Ao escrever para uma equipe que já conhece o projeto, uma mensagem direta pode ser eficiente; para pessoas externas, termos internos precisam ser explicados. Registro não é uma escala única de educação: depende da relação, do canal e do que o leitor precisa fazer. Compare duas versões e confira se o tom, a informação e a expectativa continuam alinhados.",grammarTitle:"Escolhas de registro",grammar:"Could you…? e Would you mind…? podem suavizar pedidos; a escolha depende da relação e do custo da ação. Hi/Hello não são automaticamente inadequados em mensagens profissionais. Preserve o conteúdo central e ajuste explicitude, saudação e contexto, em vez de adicionar formalidade vazia.",phrases:[{english:"Could you send the revised file by Thursday?",portuguese:"Você poderia enviar o arquivo revisado até quinta-feira?",note:"Pedido cortês com ação e prazo explícitos."},{english:"Please find the revised file attached.",portuguese:"Segue anexado o arquivo revisado.",note:"Fórmula convencional de e-mail; escolha conforme canal e público."},{english:"Would you mind checking the access settings?",portuguese:"Você se importaria de verificar as configurações de acesso?",note:"Would you mind + verbo-ing faz pedido indireto."},{english:"Hi, team—here is the short update.",portuguese:"Olá, equipe — segue a atualização breve.",note:"Tom familiar pode ser apropriado com equipe conhecida."}],examples:[{english:"Could you send the revised file by Thursday?",portuguese:"Você poderia enviar o arquivo revisado até quinta-feira?"},{english:"Would you mind checking the access settings?",portuguese:"Você se importaria de verificar as configurações de acesso?"},{english:"Please find the revised file attached.",portuguese:"Segue anexado o arquivo revisado."},{english:"Hi, team—here is the short update.",portuguese:"Olá, equipe — segue a atualização breve."}],practice:[{prompt:"Um leitor externo não conhece a sigla interna. Qual versão ajuda mais?",options:["Spell out the term once and then define the abbreviation.","Use the abbreviation without explanation.","Add several formal greetings."],answer:0,explanation:"Definição resolve a lacuna de conhecimento, não apenas o tom."},{prompt:"Complete: “Would you mind ___ the date?”",options:["confirming","confirm","to confirm"],answer:0,explanation:"Mind é seguido de gerúndio."},{prompt:"Que elemento convém manter ao adaptar um e-mail?",options:["The action and deadline","Every original phrase","Unexplained internal shorthand"],answer:0,explanation:"A adaptação preserva a ação e o prazo essenciais."},{prompt:"Qual escolha considera relação e canal?",options:["Choose a concise greeting suitable for the recipient and context.","Use the longest greeting in every message.","Remove the purpose of the message."],answer:0,explanation:"Registro depende da audiência e do canal."}],takeaway:"Antes de enviar, identifique leitor e ação esperada; ajuste saudação e explicações sem ocultar pedido ou prazo."},
  { id:"softening-a-position",title:"A more measured view",subtitle:"Apresente desacordo com ressalvas bem calibradas.",objective:"Expressar discordância com ressalva, evidência atribuída e posição própria delimitada.",focus:"Modalização e discordância",intro:"Em uma revisão, alguém pode dizer que a proposta sempre reduzirá atrasos. Se você discorda, refute o alcance da afirmação, não a pessoa. Expressões de cautela permitem separar o que os dados sugerem daquilo que ainda precisa ser verificado. Suavizar não significa abandonar a posição: diga claramente qual conclusão é sustentada e em que condição.",grammarTitle:"Modalizadores e concessão",grammar:"It may be that / the evidence appears to… reduz força da afirmação; I’m not fully convinced by… sinaliza discordância com foco na ideia. Although concede um ponto; however conduz à ressalva. Use perhaps com parcimônia: acumular hedge pode tornar a posição indecifrável.",phrases:[{english:"I’m not fully convinced that the change explains the entire difference.",portuguese:"Não estou totalmente convencida de que a mudança explique toda a diferença.",note:"A ressalva limita uma afirmação causal ampla."},{english:"The early figures appear to show a modest improvement.",portuguese:"Os primeiros números parecem mostrar uma melhora modesta.",note:"Appear to calibra conclusão provisória."},{english:"Although access improved, the sample was limited.",portuguese:"Embora o acesso tenha melhorado, a amostra foi limitada.",note:"Although reconhece avanço e introduz limitação."},{english:"I would support a longer trial before drawing a firm conclusion.",portuguese:"Eu apoiaria um teste mais longo antes de chegar a uma conclusão firme.",note:"Posição clara e condição para decisão mais robusta."}],examples:[{english:"I’m not fully convinced that the change explains the entire difference.",portuguese:"Não estou totalmente convencida de que a mudança explique toda a diferença."},{english:"The early figures appear to show a modest improvement.",portuguese:"Os primeiros números parecem mostrar uma melhora modesta."},{english:"Although access improved, the sample was limited.",portuguese:"Embora o acesso tenha melhorado, a amostra foi limitada."},{english:"I would support a longer trial before drawing a firm conclusion.",portuguese:"Eu apoiaria um teste mais longo antes de chegar a uma conclusão firme."}],practice:[{prompt:"Qual discordância mantém foco na alegação?",options:["I’m not convinced the sample supports that broad conclusion.","You never understand the data.","Every conclusion is equally true."],answer:0,explanation:"A primeira questiona a relação entre amostra e conclusão."},{prompt:"Complete: “The figures ___ to suggest a small change.”",options:["appear","appears","appearing"],answer:0,explanation:"Figures é plural; appear concorda."},{prompt:"Qual conectivo introduz uma concessão?",options:["although","therefore","instead of that"],answer:0,explanation:"Although apresenta uma ressalva concessiva."},{prompt:"Como evitar hesitação excessiva?",options:["State the position and specify one relevant limitation.","Add perhaps to every clause.","Avoid saying what you think."],answer:0,explanation:"Uma ressalva pertinente acompanha uma posição explícita."}],takeaway:"Separe ideia e pessoa; declare seu grau de confiança, conceda um ponto válido e delimite a conclusão."},
  { id:"reading-between-the-lines",title:"What is implied?",subtitle:"Identifique pressupostos e implicações em textos.",objective:"Inferir uma implicação textual citando pistas linguísticas e distinguindo inferência de informação explícita.",focus:"Implicatura e pressupostos",intro:"Uma nota diz que a equipe “finally” recebeu acesso. O advérbio pode sugerir espera ou atraso, mas o contexto não prova por si só por que isso ocorreu. Ao ler nas entrelinhas, registre as palavras que sustentam uma hipótese e considere interpretações alternativas. Diferencie o que o texto afirma literalmente daquilo que você infere.",grammarTitle:"Inferência cautelosa",grammar:"Suggests / implies introduzem inferência; explicitly states marca conteúdo direto. The word finally can imply… vincula leitura a pista. Could also reflect… oferece alternativa. Evite converter um pressuposto lexical em certeza sobre intenção do autor.",phrases:[{english:"The word ‘finally’ may imply that access was delayed.",portuguese:"A palavra ‘finalmente’ pode sugerir que o acesso foi adiado.",note:"May mantém a inferência como possibilidade."},{english:"The note explicitly states that access began on Monday.",portuguese:"A nota afirma explicitamente que o acesso começou na segunda-feira.",note:"Explicitly separa informação literal."},{english:"The wording could also reflect the writer’s relief.",portuguese:"A formulação também pode refletir o alívio de quem escreveu.",note:"Apresenta leitura alternativa plausível."},{english:"We need more context before inferring who caused the delay.",portuguese:"Precisamos de mais contexto antes de inferir quem causou o atraso.",note:"Evita atribuição causal sem suporte."}],examples:[{english:"The word ‘finally’ may imply that access was delayed.",portuguese:"A palavra ‘finalmente’ pode sugerir que o acesso foi adiado."},{english:"The note explicitly states that access began on Monday.",portuguese:"A nota afirma explicitamente que o acesso começou na segunda-feira."},{english:"The wording could also reflect the writer’s relief.",portuguese:"A formulação também pode refletir o alívio de quem escreveu."},{english:"We need more context before inferring who caused the delay.",portuguese:"Precisamos de mais contexto antes de inferir quem causou o atraso."}],practice:[{prompt:"Texto: “The revised plan is finally available.” O que é explícito?",options:["The revised plan is available now.","The author blames one person.","The plan is a failure."],answer:0,explanation:"A disponibilidade atual é afirmada; culpa e avaliação não são."},{prompt:"Qual formulação marca inferência cautelosa?",options:["The wording may suggest prior delay.","The wording proves deliberate obstruction.","No inference can ever be made."],answer:0,explanation:"May suggest declara hipótese, não certeza."},{prompt:"Que prática melhora a leitura implícita?",options:["Quote the cue and consider another plausible reading.","Ignore surrounding context.","Assume the writer’s intention."],answer:0,explanation:"Pista mais contexto e alternativa sustentam inferência responsável."},{prompt:"Qual verbo indica conteúdo literal?",options:["explicitly states","might imply","could suggest"],answer:0,explanation:"Explicitly states marca afirmação direta."}],takeaway:"Cite a pista textual, formule a inferência como hipótese e teste ao menos uma leitura alternativa."},
  { id:"irony-and-understatement",title:"Not quite what it seems",subtitle:"Interprete ironia e eufemismo em contexto.",objective:"Interpretar ironia ou understatement usando contraste contextual e indicar quando a intenção permanece ambígua.",focus:"Ironia, eufemismo e contexto",intro:"Após uma apresentação interrompida várias vezes, alguém comenta “That went perfectly.” O contraste pode sinalizar ironia, mas tom, relação e contexto importam. O understatement também pode reduzir deliberadamente a intensidade. Evite interpretar sarcasmo como fato literal; explique quais pistas apoiam sua leitura e pergunte quando a consequência social for importante.",grammarTitle:"Contraste entre sentido literal e intenção",grammar:"Ironia depende de discrepância entre enunciado e situação; would have been better pode expressar crítica indireta. Acknowledge uncertainty com might be ironic. Não há marcador gramatical obrigatório: entonação e relação ajudam, mas não autorizam certeza sobre intenção privada.",phrases:[{english:"‘Perfect timing,’ she said as the meeting started without the presenter.",portuguese:"‘Pontualidade perfeita’, disse ela quando a reunião começou sem a apresentadora.",note:"Contraste contextual sugere ironia."},{english:"The delay was a little inconvenient.",portuguese:"O atraso foi um pouco inconveniente.",note:"Understatement pode reduzir a força de uma crítica."},{english:"That comment might be ironic, but the context is limited.",portuguese:"Esse comentário pode ser irônico, mas o contexto é limitado.",note:"Might qualifica a interpretação."},{english:"Could you clarify what you meant by ‘interesting’?",portuguese:"Você poderia esclarecer o que quis dizer com ‘interessante’?",note:"Pergunta direta evita adivinhar intenção ambígua."}],examples:[{english:"‘Perfect timing,’ she said as the meeting started without the presenter.",portuguese:"‘Pontualidade perfeita’, disse ela quando a reunião começou sem a apresentadora."},{english:"The delay was a little inconvenient.",portuguese:"O atraso foi um pouco inconveniente."},{english:"That comment might be ironic, but the context is limited.",portuguese:"Esse comentário pode ser irônico, mas o contexto é limitado."},{english:"Could you clarify what you meant by ‘interesting’?",portuguese:"Você poderia esclarecer o que quis dizer com ‘interessante’?"}],practice:[{prompt:"Uma frase positiva acompanha uma falha evidente. Qual leitura é mais cautelosa?",options:["The contrast may signal irony.","The speaker definitely intended harm.","The event was literally perfect."],answer:0,explanation:"May signal considera contraste sem afirmar intenção."},{prompt:"Understatement geralmente…",options:["reduces the apparent force of a point","states the opposite in every case","removes all context"],answer:0,explanation:"Understatement minimiza deliberadamente a intensidade."},{prompt:"Quando uma expressão é ambígua e relevante, o que fazer?",options:["Ask what the speaker meant.","Attribute a motive as fact.","Ignore the concern."],answer:0,explanation:"Perguntar permite esclarecer significado."},{prompt:"Que evidência ajuda a interpretar ironia?",options:["The contrast between words and situation","The dictionary meaning alone","A guess about personality"],answer:0,explanation:"O contraste contextual é pista central, mas deve ser lido com cuidado."}],takeaway:"Considere palavras, situação, entonação e relação; quando a intenção importar e continuar incerta, pergunte em vez de atribuí-la."},
  { id:"tone-revision-studio",title:"One idea, three audiences",subtitle:"Reescreva uma mensagem para públicos distintos.",objective:"Adaptar uma atualização para equipe técnica, liderança e público geral preservando decisão, condição e próximo passo.",focus:"Audiência, jargão e revisão",intro:"Uma equipe técnica precisa conhecer um problema de integração; a liderança precisa saber impacto e decisão pendente; o público geral precisa de informação clara e não alarmista. O conteúdo factual deve permanecer consistente. Ajuste vocabulário, explique termos e escolha o nível de detalhe que permite a cada leitor agir. Revisar tom não significa retirar limitação importante.",grammarTitle:"Voz passiva e informação central",grammar:"Use postponed pending review quando a condição ainda está aberta; once the review is complete indica sequência futura. Preserve modalização e escopo. Para audiência geral, substitua jargão por descrição concreta; para equipe técnica, mantenha termos necessários e defina ambiguidades. Não invente agente ou prazo.",phrases:[{english:"The release is postponed while the access review continues.",portuguese:"A publicação está adiada enquanto a revisão de acesso continua.",note:"A condição ainda está em andamento."},{english:"We will confirm a new date after the review is complete.",portuguese:"Confirmaremos uma nova data depois que a revisão estiver concluída.",note:"Não promete data antes da condição."},{english:"The system is checking who can view shared files.",portuguese:"O sistema está verificando quem pode ver os arquivos compartilhados.",note:"Explica a revisão sem jargão especializado."},{english:"No revised date has been confirmed.",portuguese:"Nenhuma nova data foi confirmada.",note:"Explicita o que ainda não se sabe."}],examples:[{english:"The release is postponed while the access review continues.",portuguese:"A publicação está adiada enquanto a revisão de acesso continua."},{english:"We will confirm a new date after the review is complete.",portuguese:"Confirmaremos uma nova data depois que a revisão estiver concluída."},{english:"The system is checking who can view shared files.",portuguese:"O sistema está verificando quem pode ver os arquivos compartilhados."},{english:"No revised date has been confirmed.",portuguese:"Nenhuma nova data foi confirmada."}],practice:[{prompt:"Qual informação deve permanecer em todas as versões?",options:["The release is postponed pending review.","A technical acronym unexplained to every audience.","A new date that has not been confirmed."],answer:0,explanation:"A condição de adiamento é informação essencial."},{prompt:"Como adaptar ‘permission audit’ ao público geral?",options:["Explain it as a check of who can access the files.","Keep the term without explanation.","Remove the reason for the delay."],answer:0,explanation:"Descrição concreta reduz barreira de jargão."},{prompt:"Complete: “We’ll confirm the date once the review ___ complete.”",options:["is","are","be"],answer:0,explanation:"Review é singular e usa is."},{prompt:"Qual edição evita promessa indevida?",options:["We will share a date after the review.","The new date is certainly tomorrow.","The review guarantees a launch."],answer:0,explanation:"A primeira condiciona anúncio à conclusão real."}],takeaway:"Mantenha decisão e condições estáveis, explique termos conforme o público e não transforme previsão incerta em promessa."},
  { id:"synthesizing-multiple-sources",title:"A coherent synthesis",subtitle:"Integre fontes sem repetir a estrutura delas.",objective:"Sintetizar duas fontes identificando convergência, diferença de método e limite de conclusão com atribuição explícita.",focus:"Síntese e atribuição",intro:"Uma entrevista e um registro administrativo podem tratar do mesmo serviço, mas responder perguntas diferentes. A síntese conecta fontes por uma questão, não as resume em sequência isolada. Mostre onde convergem, onde divergem e se as diferenças podem decorrer de método ou população. Não esconda incompatibilidades nem trate fontes distintas como se medissem exatamente a mesma coisa.",grammarTitle:"Reporting verbs e contraste",grammar:"Both sources indicate… comunica convergência; whereas / while marcam contraste. The interview participants described atribui percepção; the log recorded atribui registro. Taken together introduz síntese, mas explicite o que a combinação permite e o que não permite inferir.",phrases:[{english:"Both sources point to longer waits during the same period.",portuguese:"Ambas as fontes apontam esperas mais longas no mesmo período.",note:"Point to indica convergência sem prova causal."},{english:"The interviews describe confusion, whereas the log records repeat contacts.",portuguese:"As entrevistas descrevem confusão, enquanto o registro anota contatos repetidos.",note:"Cada fonte mantém seu tipo de observação."},{english:"Taken together, they suggest a question for further review.",portuguese:"Em conjunto, sugerem uma questão para análise posterior.",note:"Síntese cuidadosa não afirma explicação definitiva."},{english:"The sources do not measure the same population.",portuguese:"As fontes não medem a mesma população.",note:"Limite comparativo explícito."}],examples:[{english:"Both sources point to longer waits during the same period.",portuguese:"Ambas as fontes apontam esperas mais longas no mesmo período."},{english:"The interviews describe confusion, whereas the log records repeat contacts.",portuguese:"As entrevistas descrevem confusão, enquanto o registro anota contatos repetidos."},{english:"Taken together, they suggest a question for further review.",portuguese:"Em conjunto, sugerem uma questão para análise posterior."},{english:"The sources do not measure the same population.",portuguese:"As fontes não medem a mesma população."}],practice:[{prompt:"Qual síntese atribui corretamente fontes diferentes?",options:["Interviews describe confusion; the log records repeat contacts.","The log proves what every interviewee felt.","All sources measure the same thing."],answer:0,explanation:"A primeira preserva diferenças metodológicas."},{prompt:"Qual expressão marca contraste?",options:["whereas","taken together","both"],answer:0,explanation:"Whereas introduz comparação contrastiva."},{prompt:"Duas fontes convergem. Isso automaticamente prova causa?",options:["No; it supports a pattern but causation needs appropriate evidence.","Yes, any agreement proves cause.","No source can ever inform analysis."],answer:0,explanation:"Convergência não basta para causalidade."},{prompt:"O que fazer se métodos diferem?",options:["State the difference and limit the comparison.","Hide the difference.","Combine numbers without context."],answer:0,explanation:"Explicitar diferença evita falsa equivalência."}],takeaway:"Organize a síntese por pergunta, atribua achados ao método e explicite convergências e limites."},
  { id:"cause-correlation-and-claims",title:"What the data can say",subtitle:"Distinga causalidade, correlação e afirmação.",objective:"Revisar uma conclusão para distinguir associação observada de causa demonstrada e identificar informação necessária para alegação causal.",focus:"Causalidade e associação",intro:"Se duas variáveis mudam juntas, isso não estabelece que uma causou a outra. Pode haver fator comum, seleção ou coincidência temporal. Leia o desenho da investigação e o tipo de comparação antes de escolher verbos. Uma formulação precisa pode relatar associação e explicar que outros fatores ainda precisam ser examinados.",grammarTitle:"Verbos de evidência e cautela",grammar:"Was associated with relata associação; caused exige desenho capaz de sustentar causalidade. The data suggest é mais cauteloso que prove. To assess whether X caused Y, identifique comparação e fatores alternativos. Evite converter correlação temporal em explicação.",phrases:[{english:"Higher attendance was associated with the reminder.",portuguese:"Maior presença esteve associada ao lembrete.",note:"Associated with não declara causa."},{english:"The comparison does not establish what caused the change.",portuguese:"A comparação não estabelece o que causou a mudança.",note:"Limite causal explícito."},{english:"A further test could examine alternative explanations.",portuguese:"Um teste adicional poderia examinar explicações alternativas.",note:"Could sinaliza investigação possível."},{english:"The result applies to the groups included in the analysis.",portuguese:"O resultado se aplica aos grupos incluídos na análise.",note:"Delimita generalização à amostra."}],examples:[{english:"Higher attendance was associated with the reminder.",portuguese:"Maior presença esteve associada ao lembrete."},{english:"The comparison does not establish what caused the change.",portuguese:"A comparação não estabelece o que causou a mudança."},{english:"A further test could examine alternative explanations.",portuguese:"Um teste adicional poderia examinar explicações alternativas."},{english:"The result applies to the groups included in the analysis.",portuguese:"O resultado se aplica aos grupos incluídos na análise."}],practice:[{prompt:"Dois eventos variam juntos. Qual afirmação é apropriada?",options:["They are associated in this dataset.","One definitively caused the other.","They cannot be related."],answer:0,explanation:"Relata padrão observado sem extrapolar."},{prompt:"Complete: “The comparison does not ___ causation.”",options:["establish","establishes","establishing"],answer:0,explanation:"Depois de does not, use forma base."},{prompt:"Qual pergunta ajuda a avaliar uma alegação causal?",options:["What alternative factors or comparison groups were examined?","Which headline sounds strongest?","Can we ignore the study design?"],answer:0,explanation:"Fatores alternativos e comparação são relevantes."},{prompt:"Qual verbo expressa apoio sem prova conclusiva?",options:["suggests","guarantees","proves every case"],answer:0,explanation:"Suggests calibra a interpretação."}],takeaway:"Descreva o padrão e o que o desenho permite inferir; reserve verbos causais para evidência adequada."},
  { id:"explaining-uncertainty",title:"What we know and don’t",subtitle:"Comunique limites e graus de confiança.",objective:"Comunicar um achado separando observação, inferência, nível de confiança e próximo dado necessário.",focus:"Linguagem epistêmica",intro:"Uma equipe dispõe de registros incompletos, mas precisa decidir se investiga um padrão. Comunique o que aparece sem fingir precisão. Explique quais dados estão presentes, o que sugerem e qual informação falta. Termos como likely, possible e unclear têm funções diferentes; use-os de modo consistente com evidência e consequência da decisão.",grammarTitle:"Modalização e evidência",grammar:"The records show relata observação; this may indicate introduz inferência; it remains unclear declara lacuna. Likely sugere probabilidade maior que possible, mas não é número sem calibração. Use based on the available records para explicitar limite.",phrases:[{english:"The records show a rise in repeat requests.",portuguese:"Os registros mostram aumento de pedidos repetidos.",note:"Atribui observação ao registro."},{english:"This may indicate that instructions need review.",portuguese:"Isso pode indicar que as instruções precisam ser revisadas.",note:"May marca inferência possível."},{english:"It remains unclear whether the change affected all teams.",portuguese:"Ainda não está claro se a mudança afetou todas as equipes.",note:"Nomeia lacuna delimitada."},{english:"Based on the available records, confidence is limited.",portuguese:"Com base nos registros disponíveis, a confiança é limitada.",note:"Declara base e calibra confiança."}],examples:[{english:"The records show a rise in repeat requests.",portuguese:"Os registros mostram aumento de pedidos repetidos."},{english:"This may indicate that instructions need review.",portuguese:"Isso pode indicar que as instruções precisam ser revisadas."},{english:"It remains unclear whether the change affected all teams.",portuguese:"Ainda não está claro se a mudança afetou todas as equipes."},{english:"Based on the available records, confidence is limited.",portuguese:"Com base nos registros disponíveis, a confiança é limitada."}],practice:[{prompt:"Qual frase separa observação de inferência?",options:["The log records repeats; this may indicate a clarity issue.","The log proves why every person acted.","The log has entries, therefore all causes are known."],answer:0,explanation:"Separa registro e interpretação possível."},{prompt:"Qual expressão declara lacuna?",options:["It remains unclear whether","This proves that","Everyone knows"],answer:0,explanation:"Remains unclear indica algo desconhecido."},{prompt:"Quando usar likely em vez de possible?",options:["When your stated confidence supports a stronger probability judgment.","Whenever you want to sound certain.","To replace all evidence."],answer:0,explanation:"Likely é mais forte e deve corresponder à evidência."},{prompt:"Qual próximo passo é transparente?",options:["Collect missing team-level data before generalizing.","Assume absent data confirm the pattern.","Hide uncertainty from the reader."],answer:0,explanation:"Coletar informação faltante reduz a lacuna."}],takeaway:"Rotule observação, inferência e lacuna; calibre modalizadores e diga qual dado reduziria a incerteza."},
  { id:"leading-a-deep-discussion",title:"Questions that open a discussion",subtitle:"Conduza uma conversa com perguntas analíticas.",objective:"Conduzir discussão usando perguntas de esclarecimento, pressupostos e consequência, sintetizando convergência e desacordo.",focus:"Perguntas analíticas e síntese",intro:"Em uma conversa sobre uma mudança de política, perguntas fechadas podem encerrar a análise cedo. Pergunte o que um termo significa, qual pressuposto sustenta uma recomendação e quem pode ser afetado de modo diferente. Escute e resuma antes de mudar de assunto. A meta não é prolongar toda conversa, mas aprofundar pontos que alteram a decisão.",grammarTitle:"Perguntas indiretas e seguimento",grammar:"Could you clarify what you mean by…? é pergunta indireta: a ordem interna é sujeito + verbo. What assumption underlies…? busca premissa. If that is true, what follows? explora consequência. Use So, we agree on X, but differ on Y para sintetizar sem criar falso consenso.",phrases:[{english:"Could you clarify what you mean by ‘effective’ here?",portuguese:"Você poderia esclarecer o que quer dizer com ‘eficaz’ aqui?",note:"Pergunta indireta usa ordem afirmativa interna."},{english:"What assumption underlies that recommendation?",portuguese:"Que pressuposto sustenta essa recomendação?",note:"Pergunta a premissa, não a pessoa."},{english:"If that holds, who might experience a different outcome?",portuguese:"Se isso se confirmar, quem poderia ter um resultado diferente?",note:"Explora consequência e heterogeneidade."},{english:"We agree on the goal, but differ on the measure.",portuguese:"Concordamos com o objetivo, mas divergimos sobre a medida.",note:"Síntese registra convergência parcial."}],examples:[{english:"Could you clarify what you mean by ‘effective’ here?",portuguese:"Você poderia esclarecer o que quer dizer com ‘eficaz’ aqui?"},{english:"What assumption underlies that recommendation?",portuguese:"Que pressuposto sustenta essa recomendação?"},{english:"If that holds, who might experience a different outcome?",portuguese:"Se isso se confirmar, quem poderia ter um resultado diferente?"},{english:"We agree on the goal, but differ on the measure.",portuguese:"Concordamos com o objetivo, mas divergimos sobre a medida."}],practice:[{prompt:"Qual pergunta esclarece um termo vago?",options:["Could you clarify what you mean by ‘access’?","Why are you unclear?","Can we assume the same definition?"],answer:0,explanation:"Solicita definição sem acusar."},{prompt:"Complete: “Could you explain what the report ___?”",options:["shows","does show","show does"],answer:0,explanation:"Pergunta indireta mantém sujeito antes do verbo."},{prompt:"Como sintetizar divergência parcial?",options:["We share the goal but differ on the measure.","We agree on everything.","There is no shared point."],answer:0,explanation:"Registra convergência e diferença."},{prompt:"Que pergunta examina consequência?",options:["If the assumption holds, who could be affected?","Who said that first?","Can we skip implications?"],answer:0,explanation:"Explora impacto do pressuposto."}],takeaway:"Escolha pergunta que esclareça termo, pressuposto ou consequência; resuma a resposta antes de avançar."},
  { id:"c1-argument-lab",title:"Precision under pressure",subtitle:"Defenda uma ideia complexa em resposta a objeções.",objective:"Responder a objeções reformulando-as com fidelidade e defendendo tese delimitada por evidência e ressalvas.",focus:"Argumento e objeção",intro:"Em uma apresentação, alguém questiona a amostra; outra pessoa pergunta quem assume o custo. Responda cada objeção no nível correto. Não trate dúvida metodológica como rejeição do objetivo nem confunda custo com eficácia. Reformule, conceda o que a pergunta demonstra e indique que parte da recomendação permanece sustentada.",grammarTitle:"Concessão e estrutura argumentativa",grammar:"I take your point about… demonstra escuta; Granted… concede limite; nevertheless delimita o argumento restante. The evidence supports X under Y é mais preciso que X is best. Distinga objeção, resposta, suporte e conclusão.",phrases:[{english:"I take your point about the small sample.",portuguese:"Entendo seu ponto sobre a amostra pequena.",note:"Reformula foco da objeção."},{english:"Granted, the cost estimate is preliminary.",portuguese:"É verdade que a estimativa de custo é preliminar.",note:"Concede limite sem desviar."},{english:"Nevertheless, the pilot can test access before expansion.",portuguese:"Ainda assim, o piloto pode testar o acesso antes da ampliação.",note:"Defende uma etapa proporcional."},{english:"The evidence supports a limited trial, not a permanent decision.",portuguese:"As evidências apoiam um teste limitado, não uma decisão permanente.",note:"Escopo calibrado."}],examples:[{english:"I take your point about the small sample.",portuguese:"Entendo seu ponto sobre a amostra pequena."},{english:"Granted, the cost estimate is preliminary.",portuguese:"É verdade que a estimativa de custo é preliminar."},{english:"Nevertheless, the pilot can test access before expansion.",portuguese:"Ainda assim, o piloto pode testar o acesso antes da ampliação."},{english:"The evidence supports a limited trial, not a permanent decision.",portuguese:"As evidências apoiam um teste limitado, não uma decisão permanente."}],practice:[{prompt:"Objeção: a amostra é pequena. Qual resposta é pertinente?",options:["That limits generalization; a larger trial could test the pattern.","The sample size is irrelevant to every claim.","The objection proves the proposal is useless."],answer:0,explanation:"Concede limite e sugere próximo teste."},{prompt:"Qual expressão introduz concessão?",options:["Granted","Therefore","For example"],answer:0,explanation:"Granted reconhece ponto antes da resposta."},{prompt:"Como formular evidência de escopo limitado?",options:["supports a trial in the settings studied","proves the best policy everywhere","guarantees universal results"],answer:0,explanation:"Limita contexto e tipo de decisão."},{prompt:"O custo é preliminar. Qual ação é útil?",options:["Clarify what the estimate includes before comparing options.","Treat it as final audited figure.","Ignore costs altogether."],answer:0,explanation:"Verificar escopo da estimativa precede comparação."}],takeaway:"Reformule cada objeção, identifique o que limita e responda apenas à parte da tese ainda apoiada."},
  { id:"research-question-and-scope",title:"A question with a clear scope",subtitle:"Transforme um tema amplo em pergunta delimitada.",objective:"Converter tema amplo em pergunta investigável delimitando contexto, população, fenômeno e alcance factível.",focus:"Pergunta de pesquisa e escopo",intro:"Technology in education é um tema, não uma pergunta delimitada. Especifique quem, em qual cenário e qual fenômeno observará. Uma pergunta crítica não deve pressupor resposta nem prometer medir mais do que fontes acessíveis permitem. Confira se respostas diferentes poderiam ser apoiadas por evidência.",grammarTitle:"Wh-questions e delimitação",grammar:"Which factors / under what conditions abre análise; in first-year courses delimita cenário. To what extent admite grau. Não confunda pergunta com hipótese. Defina termos que podem ter mais de uma interpretação antes de coletar dados.",phrases:[{english:"How do students use feedback in first-year writing courses?",portuguese:"Como estudantes usam feedback em cursos de escrita do primeiro ano?",note:"População e cenário delimitados."},{english:"Under what conditions does the policy affect access?",portuguese:"Sob quais condições a política afeta o acesso?",note:"Abre a possibilidade de condições distintas."},{english:"The inquiry focuses on two public libraries during one term.",portuguese:"A investigação foca em duas bibliotecas públicas durante um período letivo.",note:"Limita generalização."},{english:"This question does not assume that the policy succeeds.",portuguese:"Esta pergunta não pressupõe que a política funcione.",note:"Evita conclusão embutida."}],examples:[{english:"How do students use feedback in first-year writing courses?",portuguese:"Como estudantes usam feedback em cursos de escrita do primeiro ano?"},{english:"Under what conditions does the policy affect access?",portuguese:"Sob quais condições a política afeta o acesso?"},{english:"The inquiry focuses on two public libraries during one term.",portuguese:"A investigação foca em duas bibliotecas públicas durante um período letivo."},{english:"This question does not assume that the policy succeeds.",portuguese:"Esta pergunta não pressupõe que a política funcione."}],practice:[{prompt:"Qual pergunta é mais investigável?",options:["How does evening access relate to attendance at these two sites?","Is technology good?","Why is the policy obviously successful?"],answer:0,explanation:"Delimita relação, contexto e medida."},{prompt:"Qual expressão pergunta por condições?",options:["under what conditions","as a result of","despite from"],answer:0,explanation:"Under what conditions abre pergunta condicional."},{prompt:"Hipótese é…",options:["uma expectativa testável distinta do resultado","um resultado já provado","uma opinião impossível de revisar"],answer:0,explanation:"Hipótese antecede análise e pode ser revista."},{prompt:"A pergunta excede prazo e recursos. O que fazer?",options:["Narrow its population, setting, or period.","Promise a universal answer.","Remove all context."],answer:0,explanation:"Delimitar escopo torna o projeto factível."}],takeaway:"Teste se a pergunta é delimitada, neutra e factível; declare quais evidências poderiam contrariar sua expectativa."},
  { id:"integrating-sources-responsibly",title:"Working with sources",subtitle:"Parafraseie, sintetize e atribua ideias com precisão.",objective:"Integrar duas fontes distinguindo paráfrase, síntese e citação, com atribuição rastreável e sem alterar o alcance da ideia.",focus:"Atribuição, paráfrase e síntese",intro:"Parafrasear é reconstruir ideia com suas próprias palavras e preservar significado; trocar sinônimos mantendo estrutura pode continuar próximo demais. Atribua a ideia e confira se seu escopo corresponde à fonte. Síntese relaciona fontes e acrescenta organização analítica própria, sem apagar diferenças.",grammarTitle:"Reporting verbs e atribuição",grammar:"According to X atribui; X argues / reports / finds diferencia tipo de afirmação. Use quotation marks para citação literal e indicação de fonte. In contrast / both sources ajudam síntese. Não atribua ao autor inferência sua; sinalize-a como interpretação.",phrases:[{english:"The report argues that access varies by location.",portuguese:"O relatório argumenta que o acesso varia conforme a localização.",note:"Argues atribui argumento à fonte."},{english:"Both interviews identify scheduling as a concern.",portuguese:"Ambas as entrevistas identificam o horário como preocupação.",note:"Atribui convergência às fontes consultadas."},{english:"My interpretation is that the difference may reflect the sample.",portuguese:"Minha interpretação é que a diferença pode refletir a amostra.",note:"Assume autoria da inferência."},{english:"A direct quotation should preserve the source’s wording.",portuguese:"Uma citação direta deve preservar a formulação da fonte.",note:"Citação literal exige precisão e marcação."}],examples:[{english:"The report argues that access varies by location.",portuguese:"O relatório argumenta que o acesso varia conforme a localização."},{english:"Both interviews identify scheduling as a concern.",portuguese:"Ambas as entrevistas identificam o horário como preocupação."},{english:"My interpretation is that the difference may reflect the sample.",portuguese:"Minha interpretação é que a diferença pode refletir a amostra."},{english:"A direct quotation should preserve the source’s wording.",portuguese:"Uma citação direta deve preservar a formulação da fonte."}],practice:[{prompt:"Qual frase atribui uma afirmação?",options:["The report argues that access varies.","Access varies, as everyone knows.","The source says exactly what I think."],answer:0,explanation:"Atribui explicitamente ao relatório."},{prompt:"Uma paráfrase responsável deve…",options:["preservar sentido e alcance com formulação própria","trocar sinônimos","omitir a fonte"],answer:0,explanation:"Reformular não remove a obrigação de atribuir."},{prompt:"Como sinalizar inferência própria?",options:["My interpretation is…","The author proves… sem base","Everyone concludes…"],answer:0,explanation:"Distingue interpretação do conteúdo da fonte."},{prompt:"Qual é síntese?",options:["Relacionar fontes por pergunta comum e explicar relações.","Resumir cada fonte sem conexão.","Copiar uma frase de cada texto."],answer:0,explanation:"Síntese organiza relação entre evidências."}],takeaway:"Atribua cada ideia, confira escopo na fonte e marque onde termina evidência e começa sua interpretação."},
  { id:"argument-structure",title:"A line of reasoning",subtitle:"Organize tese, evidência, ressalvas e conclusão.",objective:"Estruturar análise em tese, razão, evidência atribuída, ressalva e conclusão proporcional.",focus:"Progressão do argumento",intro:"Um texto coerente mostra como cada evidência contribui para uma conclusão. Comece pela tese, explique critério, apresente suporte e discuta limitação. Conectores não substituem lógica. Se evidência é parcial, conclusão deve refletir isso em vez de saltar para regra universal.",grammarTitle:"Conectores e referência",grammar:"Because introduz razão; therefore indica consequência quando a conexão está estabelecida. However marca contraste; this evidence deve apontar para antecedente claro. Although concede ponto que deve ser respondido. Faça cada parágrafo avançar uma função.",phrases:[{english:"The proposal meets the access criterion because it supports offline use.",portuguese:"A proposta atende ao critério de acesso porque permite uso offline.",note:"Because conecta critério e razão."},{english:"However, the cost estimate excludes staff training.",portuguese:"No entanto, a estimativa de custo exclui treinamento.",note:"Introduz limite relevante."},{english:"Taken together, these findings support a pilot.",portuguese:"Em conjunto, esses achados apoiam um piloto.",note:"Conclusão proporcional."},{english:"This limitation means the result should not be generalized yet.",portuguese:"Essa limitação significa que o resultado ainda não deve ser generalizado.",note:"This limitation retoma elemento identificável."}],examples:[{english:"The proposal meets the access criterion because it supports offline use.",portuguese:"A proposta atende ao critério de acesso porque permite uso offline."},{english:"However, the cost estimate excludes staff training.",portuguese:"No entanto, a estimativa de custo exclui treinamento."},{english:"Taken together, these findings support a pilot.",portuguese:"Em conjunto, esses achados apoiam um piloto."},{english:"This limitation means the result should not be generalized yet.",portuguese:"Essa limitação significa que o resultado ainda não deve ser generalizado."}],practice:[{prompt:"Qual sequência organiza raciocínio?",options:["Claim, reason, attributed evidence, limitation, conclusion","Conclusion, unrelated quote, claim","Connectors without a logical link"],answer:0,explanation:"A progressão deixa base e limite visíveis."},{prompt:"Complete: “___, the cost estimate excludes training.”",options:["However","Because","For instance of"],answer:0,explanation:"However introduz contraste."},{prompt:"Quando therefore é apropriado?",options:["When preceding evidence supports the stated consequence.","Whenever a sentence begins.","To replace a missing reason."],answer:0,explanation:"Therefore precisa de conexão inferencial real."},{prompt:"Como evitar referência vaga?",options:["Name the finding that ‘this evidence’ refers to.","Use this without antecedent.","Remove all evidence."],answer:0,explanation:"Referência clara ajuda a acompanhar argumento."}],takeaway:"Revise a função de cada parágrafo e se a evidência sustenta a conclusão seguinte."},
  { id:"editing-for-cohesion",title:"A text that holds together",subtitle:"Revise coesão, referências e progressão argumentativa.",objective:"Revisar texto longo localizando referência ambígua, transição abrupta e repetição, preservando relações lógicas.",focus:"Coesão e referência textual",intro:"Um leitor perde o fio quando this pode apontar para duas ideias, contudo surge sem contraste ou parágrafo muda de assunto sem ligação. Revisão de coesão não consiste em adicionar conectores a cada frase. Identifique referente, explicite relação entre ideias e retire repetição que não reforça argumento.",grammarTitle:"Pronomes, conectores e tópico",grammar:"Substitua this por this limitation quando o antecedente for amplo. In contrast exige elementos comparáveis; moreover acrescenta evidência e não oposição. Topic sentence orienta a função do parágrafo. Revise ligações sem alterar força da evidência.",phrases:[{english:"This limitation applies to the evening sample.",portuguese:"Essa limitação se aplica à amostra noturna.",note:"Nomeia referente em vez de this ambíguo."},{english:"By contrast, the second site reported stable attendance.",portuguese:"Em contraste, o segundo local relatou presença estável.",note:"Assinala comparação explícita."},{english:"Moreover, interviews identified a separate access concern.",portuguese:"Além disso, entrevistas identificaram outra preocupação de acesso.",note:"Acrescenta ponto relacionado."},{english:"The next section examines how samples were selected.",portuguese:"A próxima seção examina como as amostras foram selecionadas.",note:"Antecipa a estrutura seguinte."}],examples:[{english:"This limitation applies to the evening sample.",portuguese:"Essa limitação se aplica à amostra noturna."},{english:"By contrast, the second site reported stable attendance.",portuguese:"Em contraste, o segundo local relatou presença estável."},{english:"Moreover, interviews identified a separate access concern.",portuguese:"Além disso, entrevistas identificaram outra preocupação de acesso."},{english:"The next section examines how samples were selected.",portuguese:"A próxima seção examina como as amostras foram selecionadas."}],practice:[{prompt:"‘This affects the result’ tem dois referentes. Como revisar?",options:["Name the factor: ‘This sampling limit affects…’","Add another this.","Delete every result."],answer:0,explanation:"Nomear antecedente reduz ambiguidade."},{prompt:"Qual conector adiciona informação?",options:["Moreover","By contrast","Nevertheless"],answer:0,explanation:"Moreover introduz adição."},{prompt:"By contrast precisa de…",options:["elementos comparáveis","conclusão causal","pedido indireto"],answer:0,explanation:"Contraste requer aspectos comparáveis."},{prompt:"Qual objetivo de topic sentence?",options:["Orientar a função da ideia central.","Substituir evidência.","Repetir o título."],answer:0,explanation:"Ajuda leitor a antecipar argumento local."}],takeaway:"Revise referentes e relações primeiro; acrescente conector apenas quando nomeia relação real."},
  { id:"c1-written-analysis",title:"An analytical response",subtitle:"Escreva uma análise articulada com fontes diversas.",objective:"Redigir análise com tese delimitada, fontes atribuídas, comparação, limite e implicação para audiência definida.",focus:"Análise escrita e síntese",intro:"Uma análise não é coleção de citações. Apresenta pergunta, explica como fontes se relacionam e avalia o que métodos permitem concluir. Defina audiência e propósito; use evidência suficiente, atribuição precisa e ressalva relevante. Conclua com implicação proporcional, não recomendação maior do que investigação comporta.",grammarTitle:"Integração de fontes",grammar:"According to / the report finds atribui; whereas compara métodos; taken together sintetiza. Nevertheless deve responder ressalva anterior. Use may indicate para inferência. Preserve denominadores, período e população descritos pela fonte.",phrases:[{english:"The first report records timing; the interviews describe user experience.",portuguese:"O primeiro relatório registra horários; entrevistas descrevem experiência de usuários.",note:"Explicita contribuições metodológicas diferentes."},{english:"Taken together, the sources suggest an access question for further study.",portuguese:"Em conjunto, as fontes sugerem uma questão de acesso para pesquisa adicional.",note:"Conclusão abre investigação, não declara causa."},{english:"The available records cover one term only.",portuguese:"Os registros disponíveis cobrem apenas um período letivo.",note:"Limita alcance temporal."},{english:"This analysis therefore recommends a monitored comparison.",portuguese:"Por isso, esta análise recomenda comparação monitorada.",note:"Conecta conclusão ao argumento."}],examples:[{english:"The first report records timing; the interviews describe user experience.",portuguese:"O primeiro relatório registra horários; entrevistas descrevem experiência de usuários."},{english:"Taken together, the sources suggest an access question for further study.",portuguese:"Em conjunto, as fontes sugerem uma questão de acesso para pesquisa adicional."},{english:"The available records cover one term only.",portuguese:"Os registros disponíveis cobrem apenas um período letivo."},{english:"This analysis therefore recommends a monitored comparison.",portuguese:"Por isso, esta análise recomenda comparação monitorada."}],practice:[{prompt:"Qual conclusão é proporcional a duas fontes com métodos diferentes?",options:["They suggest a question for comparable follow-up.","They prove one cause for every user.","They are identical measures."],answer:0,explanation:"Preserva diferença de método e sugere acompanhamento."},{prompt:"Como preservar informação quantitativa?",options:["Keep population, period, and denominator clear.","Remove the denominator.","Change period to strengthen claim."],answer:0,explanation:"Contexto define o que medida representa."},{prompt:"Qual frase marca limite?",options:["The records cover one term only.","The records prove all future outcomes.","The records are always complete."],answer:0,explanation:"Delimita período coberto."},{prompt:"O que deve fazer conclusão analítica?",options:["Connect implication to evidence and scope.","Introduce unsupported certainty.","Repeat every source sentence."],answer:0,explanation:"Conclusão reflete suporte e escopo."}],takeaway:"Conecte fontes à pergunta, preserve método e escopo e encerre com implicação sustentada."},
  { id:"opening-a-complex-presentation",title:"The question behind the topic",subtitle:"Apresente o problema e a relevância para o público.",objective:"Abrir apresentação identificando problema, relevância para audiência, pergunta orientadora e mapa conciso da exposição.",focus:"Abertura, enquadramento e audiência",intro:"Uma apresentação complexa não precisa iniciar com estatística dramática. Diga qual problema será examinado, por que importa para aquela audiência e qual pergunta guia a análise. Defina termos essenciais e indique a estrutura. Se mencionar evidência preliminar, contextualize fonte e limitação. A abertura prepara a escuta sem antecipar resultado.",grammarTitle:"Pergunta orientadora e roteiro",grammar:"Today I’ll examine… enquadra; this matters to this audience because… liga ao interesse. The question is… delimita. I’ll first…, then… oferece mapa. Use will examine para plano, não como promessa de achado.",phrases:[{english:"Today I’ll examine how the schedule affects access across two sites.",portuguese:"Hoje examinarei como o cronograma afeta o acesso em dois locais.",note:"Enquadra pergunta e contexto."},{english:"This matters to our team because the decision affects service coverage.",portuguese:"Isso importa para a equipe porque a decisão afeta cobertura do serviço.",note:"Explicita relevância à audiência."},{english:"The available records cover one term, so the comparison is limited.",portuguese:"Os registros disponíveis cobrem um período, então a comparação é limitada.",note:"Contextualiza limite."},{english:"I’ll first define the measure, then compare the sites and discuss implications.",portuguese:"Primeiro definirei a medida, depois compararei os locais e discutirei implicações.",note:"Mapa fiel da apresentação."}],examples:[{english:"Today I’ll examine how the schedule affects access across two sites.",portuguese:"Hoje examinarei como o cronograma afeta o acesso em dois locais."},{english:"This matters to our team because the decision affects service coverage.",portuguese:"Isso importa para a equipe porque a decisão afeta cobertura do serviço."},{english:"The available records cover one term, so the comparison is limited.",portuguese:"Os registros disponíveis cobrem um período, então a comparação é limitada."},{english:"I’ll first define the measure, then compare the sites and discuss implications.",portuguese:"Primeiro definirei a medida, depois compararei os locais e discutirei implicações."}],practice:[{prompt:"Qual abertura orienta sem exagerar?",options:["State the question, audience relevance, scope, and structure.","Begin with an unverified dramatic statistic.","Announce answer before evidence."],answer:0,explanation:"Oferece enquadramento e percurso."},{prompt:"Qual frase relaciona assunto à audiência?",options:["This matters to our team because…","This is a topic.","Everyone knows this is important."],answer:0,explanation:"Nomeia razão para aquele público."},{prompt:"Dados cobrem um período. O que dizer?",options:["The comparison is limited to that period.","The pattern will continue forever.","The limitation is irrelevant."],answer:0,explanation:"Afirmação acompanha alcance observado."},{prompt:"Qual frase apresenta roteiro?",options:["I’ll first define the measure, then compare the sites.","The answer is obvious.","There is no structure."],answer:0,explanation:"Sinaliza sequência sem fingir conclusão."}],takeaway:"Estruture abertura em pergunta, relevância, escopo e roteiro; confira se cada afirmação tem suporte."},
];
function makeLesson(seed: Seed): Lesson { return { id:seed.id, slug:seed.id, title:seed.title, subtitle:seed.subtitle, objective:seed.objective, focus:seed.focus, intro:seed.intro, duration:14, grammar:{title:seed.grammarTitle,explanation:seed.grammar,examples:seed.examples}, phrases:seed.phrases, practice:seed.practice, takeaway:seed.takeaway }; }
export const c1Modules: A1Module[] = [
 { id:"precision-and-register",title:"Precisão e registro",subtitle:"Adapte linguagem, ênfase e estrutura a públicos diferentes.",lessons:seeds.slice(0,10).map(makeLesson) },
 { id:"academic-and-professional-c1",title:"Inglês acadêmico e profissional",subtitle:"Leia criticamente, escreva com rigor e apresente análises.",lessons:seeds.slice(10).map(makeLesson) },
];
